import{_ as s,l,o as a,c as i,v as o,p as n,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"存储一致性模型","description":"","frontmatter":{"title":"存储一致性模型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-consistency.md","filePath":"cs/memory-consistency.md","lastUpdated":1789023840000}'),m={name:"cs/memory-consistency.md"};function E(h,e,C,S,A,_){const r=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="存储一致性模型" tabindex="-1">存储一致性模型 <a class="header-anchor" href="#存储一致性模型" aria-label="Permalink to &quot;存储一致性模型&quot;">​</a></h1><div class="epigraph"><p>一致性保证同一地址上的副本跟上写；一致性模型规定不同地址上的读写，他核看来可以是哪种交错。</p><footer>—— 据 Lamport, How to Make a Multiprocessor Computer That Correctly Executes Multiprocess Programs, IEEE TC 1979 整理</footer></div><p><a href="/cs/snoop-vs-directory">上一课</a>让一行在多核间不会长期分叉。<a href="/cs/ooo-rob">乱序与 ROB</a>允许核内 store 缓冲在提交前就执行。本课不重讲 M/E/S/I。缺口是：核 0 写 <code>x</code> 再写 <code>y</code>，核 1 能否先看见新 <code>y</code> 再看见旧 <code>x</code>？MESI 逐行处理，不回答。本课只钉顺序一致性作为规范，并指出放宽模型允许 store 缓冲对性能的意义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lamport 的顺序一致性（SC）：存在一个所有操作的全序，与每个核自己的程序序一致，且每次读返回该序下最近的写。程序员可以把多核想成「一条指令一条指令地交错」。缺口不是新的 cache 状态，而是<strong>核间可见性是否允许打乱每核的 store/load 序</strong>。</p><p>硬件若坚持 SC，store 缓冲必须对别的核不可见直到排在前面的 store 全部全局可见，延迟上升。总存储序（TSO）允许把后到的 load 提前到未耗尽的 store 之前，x86 接近这一类。本课不枚举 ARM/RISC-V 的弱模型细则，只承认有放宽，并用 fence 恢复 SC 片段。</p><p><span class="marginnote">Coherence 是单变量；SC 是多变量上的交错。两者都要，不能互相替代。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把每个核的访存看成程序序队列。SC 要求全局交错尊重这些队列。实现：提交 store 时按程序序注入 MESI 事务，load 不得越过更早的未完成 store（对 SC）。放宽后，lock 与发布-获取用栅栏指令把关键的两对变成 SC。</p>',9)),(a(),n(p,null,{default:t(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20P0%5B%22%E6%A0%B8%200%20%E7%A8%8B%E5%BA%8F%E5%BA%8F%22%5D%20--%3E%20SC%5B%22%E5%AD%98%E5%9C%A8%E5%85%A8%E5%B1%80%E4%BA%A4%E9%94%99%22%5D%0A%20%20P1%5B%22%E6%A0%B8%201%20%E7%A8%8B%E5%BA%8F%E5%BA%8F%22%5D%20--%3E%20SC%0A%20%20SC%20--%3E%20RD%5B%22%E8%AF%BB%E8%BF%94%E5%9B%9E%E8%AF%A5%E5%BA%8F%E6%9C%80%E8%BF%91%E5%86%99%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>数据竞争：无序并发访问同一地址且至少一写，SC 下仍有定义，弱模型下往往无定义。本课只点名，不把 C++ 内存模型写完。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MESI 提供单行的「当前值」；一致性模型提供多行之间的先后。store 缓冲、乱序 load、写原子性失败（一对对齐写被拆成两次可见）都会打破 SC。教学上先假设对齐字写是原子的。标志变量与数据之间的配对，正是多地址顺序要管的那一类。</p><p>栅栏对 CPI 是额外停顿：把缓冲抽干、禁止重排。阿姆达尔再次适用——只在同步点付费。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入线性一致性作为分布式对象规范，不把 Lamport 时钟写进来。也不把 MESI 的总线序直接等同于 SC：窥探实现常常给出比 SC 更强的单行序，多行仍靠缓冲打破 SC。</p><p>后课默认：谈到共享内存正确性，先问模型是 SC 还是放宽。互连延迟会让「全局可见」更贵，那是 NUMA 课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MESI 管单地址副本；SC 管多地址交错是否尊重程序序。</li><li>放宽模型换 store 缓冲性能，同步点用栅栏收回。</li><li>片上互连与远程内存延迟是下一课。</li><li>本课不把 C++ 内存模型或 Lamport 时钟写进来。</li><li>出处：Lamport, <em>IEEE TC</em>, 1979；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const f=s(m,[["render",E]]);export{B as __pageData,f as default};
